            <div class="text-caption text-grey">{{ formatNodeType(store.selectedNode.node_type) }}</div>
          </q-card-section>
        </q-card>

        <!-- Confidence -->
        <div class="row justify-between items-center q-mb-sm">
          <span class="text-caption">{{ $t('confidence') }}</span>
          <q-badge
            :color="store.selectedNode.confidence >= 0.9 ? 'positive' : store.selectedNode.confidence >= 0.7 ? 'warning' : 'negative'"
          >
            {{ (store.selectedNode.confidence * 100).toFixed(1) }}%
          </q-badge>
        </div>

        <!-- Metadata -->
        <q-expansion-item :label="$t('metadata')" dense default-opened v-if="Object.keys(store.selectedNode.metadata || {}).length > 0">
          <div class="q-pa-xs">
            <div
              v-for="(value, key) in store.selectedNode.metadata"
              :key="key"
              class="row q-mb-xs"
            >
              <span class="text-caption text-grey col-5">{{ formatMetadataKey(String(key)) }}</span>
              <span class="text-caption col-7">{{ formatMetadataValue(String(key), value) }}</span>
            </div>
          </div>
        </q-expansion-item>

        <!-- Connected Nodes -->
        <div class="q-mt-sm">
          <div class="text-caption text-bold q-mb-xs">
            {{ $t('connected_nodes') }} ({{ store.connectedNodes.length }})
          </div>
          <q-list dense separator>
            <q-item
              v-for="cn in store.connectedNodes"
              :key="cn.id"
              clickable
              dense
              @click="navigateToNode(cn.id)"
            >
              <q-item-section avatar>
                <div
                  class="node-color-dot"
                  :style="{ backgroundColor: getNodeColor(cn.node_type) }"
                />
              </q-item-section>
              <q-item-section>
                <q-item-label class="text-caption">{{ cn.label || cn.entity_id }}</q-item-label>
                <q-item-label caption>{{ formatNodeType(cn.node_type) }}</q-item-label>
              </q-item-section>
              <q-item-section side>
                <q-badge v-if="getEdgeForNode(cn.id)" outline color="grey">
                  {{ formatEdgeType(getEdgeForNode(cn.id)?.edge_type || '') }}
                </q-badge>
              </q-item-section>
            </q-item>
          </q-list>
        </div>

        <!-- Expand Button -->
        <q-btn
          no-caps
          outline
          dense
          color="primary"
          icon="mdi-arrow-expand-all"
          :label="$t('expand_node')"
          class="full-width q-mt-sm"
          @click="handleExpand(store.selectedNode.id)"
        />
      </div>
    </div>

    <!-- Search Results Dialog -->
    <q-dialog v-model="showSearchResults" position="top">
      <q-card style="width: 500px; max-height: 400px">
        <q-card-section class="q-pa-sm">
          <div class="text-subtitle2">{{ $t('search_results') }} ({{ store.searchResults.length }})</div>
        </q-card-section>
        <q-separator />
        <q-list separator style="max-height: 320px; overflow: auto">
          <q-item
            v-for="result in store.searchResults"
            :key="result.id"
            clickable
            @click="selectSearchResult(result)"
          >
            <q-item-section avatar>
              <div
                class="node-color-dot"
                :style="{ backgroundColor: getNodeColor(result.node_type) }"
              />
            </q-item-section>
            <q-item-section>
              <q-item-label>{{ result.label || result.entity_id }}</q-item-label>
              <q-item-label caption>{{ formatNodeType(result.node_type) }} - {{ result.entity_id }}</q-item-label>
            </q-item-section>
          </q-item>
          <q-item v-if="store.searchResults.length === 0">
            <q-item-section class="text-center text-grey">
              {{ $t('no_results') }}
            </q-item-section>
          </q-item>
        </q-list>
      </q-card>
    </q-dialog>
  </q-page>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref, computed, onMounted, nextTick } from 'vue';
import { VueFlow, useVueFlow, PanelPosition } from '@vue-flow/core';
import { MiniMap, Background } from '@vue-flow/additional-components';
import VueApexCharts from 'vue3-apexcharts';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { useGraphExplorerStore, NODE_COLORS, NODE_ICONS, EDGE_LABELS, type GraphNodeData } from 'src/store/graph-explorer.store';
import { graphExplorerApiService } from 'src/services';
import { whenRegionReady } from 'src/pages/api-base-url';

import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  name: 'GraphExplorer',
  components: {
    VueFlow,
    MiniMap,
    Background,
    SubHeader,
    apexchart: VueApexCharts,
  },
  setup() {
    const store = useGraphExplorerStore();
    const { fitView } = useVueFlow();
    const { t } = useTranslate();
    const searchQuery = ref('');
    const showSearchResults = ref(false);

    const availableNodeTypes = [
      { value: 'document', label: 'Documents' },
      { value: 'vendor', label: 'Vendors' },
      { value: 'purchase_order', label: 'Purchase Orders' },
      { value: 'material', label: 'Materials' },
      { value: 'invoice', label: 'Invoices' },
      { value: 'customer', label: 'Customers' },
      { value: 'shipment', label: 'Shipments' },
    ];

    const graphViewOptions = [
      { value: 'vendor-hub', label: 'Vendor Overview' },
      { value: 'vendor-table', label: 'Vendor Intelligence' },
      { value: 'process-mining', label: 'Document Journey' },
      { value: 'anomalies', label: 'Anomalies' },
    ];

    // Hub-spoke layout: hubs in center ring, spokes around each hub
    function computeHubLayout(nodes: GraphNodeData[]) {
      const positions: Record<string, { x: number; y: number }> = {};
      const hubs = nodes.filter((n) => store.hubNodeIds.includes(n.id));
      const spokes = nodes.filter((n) => !store.hubNodeIds.includes(n.id));

      // Place hubs in a circle
      const hubRadius = Math.max(300, hubs.length * 60);
      const centerX = 600;
      const centerY = 500;
      const hubPositions: Record<string, { x: number; y: number }> = {};

      hubs.forEach((hub, i) => {
        const angle = (2 * Math.PI * i) / Math.max(hubs.length, 1);
        const pos = {
          x: centerX + hubRadius * Math.cos(angle),
          y: centerY + hubRadius * Math.sin(angle),
        };
        positions[hub.id] = pos;
        hubPositions[hub.id] = pos;
      });

      // Build spoke-to-hub mapping from edges
      const spokeToHub: Record<string, string> = {};
      for (const edge of store.edges) {
        if (store.hubNodeIds.includes(edge.source_node_id) && !store.hubNodeIds.includes(edge.target_node_id)) {
          spokeToHub[edge.target_node_id] = edge.source_node_id;
        } else if (store.hubNodeIds.includes(edge.target_node_id) && !store.hubNodeIds.includes(edge.source_node_id)) {
          spokeToHub[edge.source_node_id] = edge.target_node_id;
        }
      }

      // Group spokes by their hub
      const hubSpokes: Record<string, GraphNodeData[]> = {};
      const orphanSpokes: GraphNodeData[] = [];
      for (const spoke of spokes) {
        const hubId = spokeToHub[spoke.id];
        if (hubId && hubPositions[hubId]) {
          (hubSpokes[hubId] ||= []).push(spoke);
        } else {
          orphanSpokes.push(spoke);
        }
      }

      // Place spokes around their hub
      for (const [hubId, spokeNodes] of Object.entries(hubSpokes)) {
        const hp = hubPositions[hubId];
        const spokeRadius = Math.max(150, spokeNodes.length * 12);
        spokeNodes.forEach((spoke, i) => {
          const angle = (2 * Math.PI * i) / spokeNodes.length;
          positions[spoke.id] = {
            x: hp.x + spokeRadius * Math.cos(angle),
            y: hp.y + spokeRadius * Math.sin(angle),
          };
        });
      }

      // Place orphans at the bottom
      orphanSpokes.forEach((s, i) => {
        const cols = Math.ceil(Math.sqrt(orphanSpokes.length));
        positions[s.id] = {
          x: (i % cols) * 160,
          y: centerY + hubRadius + 300 + Math.floor(i / cols) * 120,
        };
      });

      return positions;
    }

    // Grid layout: group nodes by type
    function computeGridLayout(nodes: GraphNodeData[]) {
      const groups: Record<string, GraphNodeData[]> = {};
      for (const n of nodes) {
        (groups[n.node_type] ||= []).push(n);
      }

      const positions: Record<string, { x: number; y: number }> = {};
      const nodeSpacing = 180;
      let groupOffsetY = 0;

      for (const [, groupNodes] of Object.entries(groups)) {
        const cols = Math.ceil(Math.sqrt(groupNodes.length));
        for (let i = 0; i < groupNodes.length; i++) {
          positions[groupNodes[i].id] = {
            x: (i % cols) * nodeSpacing,
            y: groupOffsetY + Math.floor(i / cols) * nodeSpacing,
          };
        }
        const rows = Math.ceil(groupNodes.length / cols);
        groupOffsetY += rows * nodeSpacing + 100;
      }
      return positions;
    }

    // Filter nodes by active type and confidence filters
    const filteredNodes = computed(() => {
      return store.nodes.filter((node) => {
        // In vendor-hub view, only show vendor hub nodes (not individual docs)
        if (store.graphView === 'vendor-hub' && store.hubNodeIds.length > 0 && !store.hubNodeIds.includes(node.id)) {
          return false;
        }
        if (store.filterNodeTypes.length > 0 && !store.filterNodeTypes.includes(node.node_type)) {
          return false;
        }
        if (store.minConfidence > 0 && node.confidence < store.minConfidence) {
          return false;
        }
        return true;
      });
    });

    const filteredNodeIds = computed(() => new Set(filteredNodes.value.map((n) => n.id)));

    // Convert graph data to Vue Flow format
    const flowNodes = computed({
      get() {
        const nodes = filteredNodes.value;
        const isHub = store.hubNodeIds.length > 0;
        const positions = isHub
          ? computeHubLayout(nodes)
          : computeGridLayout(nodes);

        return nodes.map((node) => {
          const pos = positions[node.id] || { x: 0, y: 0 };
          const isCenter = node.id === store.centerNodeId;
          const isHubNode = store.hubNodeIds.includes(node.id);
          const edgeCount = store.vendorEdgeCounts[node.id] || 0;
          const isVendorOverview = store.graphView === 'vendor-hub' && isHubNode;
          const displayLabel = isVendorOverview
            ? `${(node.label || '').substring(0, 25)}\n${edgeCount} docs`
            : (node.label || node.entity_id || '').substring(0, 30);

          return {
            id: node.id,
            type: 'graphNode',
            position: isCenter ? { x: 400, y: 300 } : pos,
            data: {
              ...node,
              displayLabel,
              typeLabel: formatNodeType(node.node_type),
              color: getNodeColor(node.node_type),
              colorName: getNodeColorName(node.node_type),
              icon: NODE_ICONS[node.node_type] || 'mdi-circle-outline',
              selected: store.selectedNode?.id === node.id,
              isHub: isHubNode,
              isVendorOverview,
              edgeCount,
            },
          };
        });
      },
      set() {
        // Vue Flow may update positions; we accept but don't sync back
      },
    });

    const flowEdges = computed({
      get() {
        const visibleIds = filteredNodeIds.value;
        return store.edges
          .filter((edge) => visibleIds.has(edge.source_node_id) && visibleIds.has(edge.target_node_id))
          .map((edge) => ({
            id: edge.id,
            source: edge.source_node_id,
            target: edge.target_node_id,
            label: EDGE_LABELS[edge.edge_type] || edge.edge_type,
            animated: edge.provenance === 'semantic',
            style: {
              strokeWidth: Math.max(1, Math.min(edge.weight, 3)),
              stroke: edge.confidence >= 0.9 ? 'rgba(76,175,80,0.4)' : edge.confidence >= 0.7 ? 'rgba(255,152,0,0.3)' : 'rgba(255,255,255,0.15)',
            },
            labelStyle: { fontSize: '10px', fill: 'rgba(255,255,255,0.5)' },
          }));
      },
      set() {
        // Vue Flow may update; we accept
      },
    });

    // Analytics chart computed properties
    const nodeTypeChartSeries = computed(() =>
      Object.values(store.stats?.nodes_by_type || {}),
    );
    const nodeTypeChartOptions = computed(() => ({
      labels: Object.keys(store.stats?.nodes_by_type || {}).map(formatNodeType),
      colors: Object.keys(store.stats?.nodes_by_type || {}).map(getNodeColor),
      legend: { position: 'bottom' as const },
    }));

    const edgeTypeChartSeries = computed(() => [{
      name: 'Edges',
      data: Object.values(store.stats?.edges_by_type || {}),
    }]);
    const edgeTypeChartOptions = computed(() => ({
      xaxis: {
        categories: Object.keys(store.stats?.edges_by_type || {}).map((t) =>
          t.split('_').map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join(' '),
        ),
      },
      colors: ['#7c3aed'],
      plotOptions: { bar: { borderRadius: 4, horizontal: true } },
    }));

    function getNodeColor(nodeType: string): string {
      return NODE_COLORS[nodeType] || '#64748b';
    }

    function getNodeColorName(nodeType: string): string {
      const map: Record<string, string> = {
        document: 'blue-10',
        vendor: 'green-10',
        purchase_order: 'deep-purple-8',
        material: 'amber-8',
        invoice: 'red-8',
        customer: 'grey-8',
        shipment: 'cyan-8',
      };
      return map[nodeType] || 'grey-7';
    }

    function formatNodeType(nodeType: string): string {
      return nodeType
        .split('_')
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    }

    function formatMetadataKey(key: string): string {
      const translated = t.value(key);
      if (translated !== key) return translated;
      return key
        .split('_')
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    }

    function formatMetadataValue(key: string, value: any): string {
      if (value === null || value === undefined || value === '') return '-';
      if (typeof value === 'number') return String(value);
      const strValue = String(value);
      const translated = t.value(strValue);
      if (translated !== strValue) return translated;
      if (key === 'doc_type') {
        const settingsKey = `settings.${strValue}`;
        const settingsTranslated = t.value(settingsKey);
        if (settingsTranslated !== settingsKey) return settingsTranslated;
      }
      return strValue
        .toLowerCase()
        .split('_')
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(' ');
    }

    function formatEdgeType(edgeType: string): string {
      return EDGE_LABELS[edgeType] || formatNodeType(edgeType);
    }

    function getNodeSize(data: any): number {
      if (data.isVendorOverview) {
        const count = data.edgeCount || 1;
        return Math.min(120, Math.max(60, 40 + count));
      }
      if (data.isHub) {
        const count = data.edgeCount || 1;
        return Math.min(80, Math.max(40, 20 + count * 2));
      }
      return 24;
    }

    function onNodeClick(data: any) {
      const node = store.nodes.find((n) => n.id === data.id);
      if (node) {
        store.selectNode(node);
      }
    }

    function getEdgeForNode(nodeId: string) {
      if (!store.selectedNode) return null;
      return store.edges.find(
        (e) =>
          (e.source_node_id === store.selectedNode!.id && e.target_node_id === nodeId) ||
          (e.target_node_id === store.selectedNode!.id && e.source_node_id === nodeId),
      );
    }

    async function loadGraph(nodeId: string, depth: number = 1) {
      store.loading = true;
      try {
        const response = await graphExplorerApiService.getNodeSubgraph(
          nodeId,
          depth,
          undefined,
          store.minConfidence,
        );
        if (response.success) {
          store.setGraphData(response.nodes, response.edges, response.center_node_id);
          await nextTick();
          setTimeout(() => fitView({ padding: 0.2 }), 100);
        }
      } catch (err: any) {
        notify.error('Failed to load graph');
      } finally {
        store.loading = false;
      }
    }

    async function handleSearch() {
      if (!searchQuery.value.trim()) return;
      store.loading = true;
      try {
        const response = await graphExplorerApiService.searchGraph(
          searchQuery.value,
          store.filterNodeTypes.length > 0 ? store.filterNodeTypes : undefined,
        );
        if (response.success) {
          store.setSearchResults(response.results);
          if (response.results.length === 1) {
            await loadGraph(response.results[0].id);
          } else {
            showSearchResults.value = true;
          }
        }
      } catch (err: any) {
        notify.error('Search failed');
      } finally {
        store.loading = false;
      }
    }

    async function selectSearchResult(result: GraphNodeData) {
      showSearchResults.value = false;
      await loadGraph(result.id);
      store.selectNode(result);
    }

    async function navigateToNode(nodeId: string) {
      await loadGraph(nodeId);
      const node = store.nodes.find((n) => n.id === nodeId);
      if (node) store.selectNode(node);
    }

    async function handleExpand(nodeId: string) {
      store.loading = true;
      try {
        const response = await graphExplorerApiService.expandNode(
          nodeId,
          2,
          undefined,
          undefined,
          store.minConfidence,
        );
        if (response.success) {
          store.setGraphData(response.nodes, response.edges, response.center_node_id);
        }
      } catch (err: any) {
        notify.error('Failed to expand node');
      } finally {
        store.loading = false;
      }
    }

    async function handleRebuild() {
      store.setComputeProgress({
        status: 'starting',
        phase: 'init',
        message: 'Starting graph computation...',
        nodes_created: 0,
        edges_created: 0,
        progress_pct: 0,
      });

      try {
        const response = await graphExplorerApiService.computeMetadataGraph(true);
        if (!response.success) {
          throw new Error(response.message || 'Failed to start graph computation');
        }

        // Sync fallback: backend returned result directly (no task_id)
        if (!response.task_id && response.nodes_created !== undefined) {
          notify.success(`Graph built: ${response.nodes_created} nodes, ${response.edges_created || 0} edges`);
          await loadStats();
          store.clearComputeProgress();
          return;
        }

        // Open SSE stream for progress
        const tokenDetails = JSON.parse(
          localStorage.getItem('token_details')?.replace('__q_objt|', '') || '{}'
        );
        const userDetails = JSON.parse(
          localStorage.getItem('user_details')?.replace('__q_objt|', '') || '{}'
        );

        await whenRegionReady();
        const streamUrl = graphExplorerApiService.getComputeProgressStreamURL(
          userDetails.org_id,
          tokenDetails.access_token,
        );

        const eventSource = new EventSource(streamUrl);

        eventSource.addEventListener('progress', (event: MessageEvent) => {
          const data = JSON.parse(event.data);
          if (data.progress) {
            store.setComputeProgress(data.progress);
          }
        });

        eventSource.addEventListener('complete', async (event: MessageEvent) => {
          const data = JSON.parse(event.data);
          if (data.progress) {
            store.setComputeProgress(data.progress);
          }
          eventSource.close();

          if (data.progress?.status === 'completed') {
            notify.success(`Graph built: ${data.progress.nodes_created} nodes, ${data.progress.edges_created} edges`);
            await loadStats();
          } else if (data.progress?.status === 'failed') {
            notify.error(data.progress.message || 'Graph computation failed');
          }

          // Clear progress after 3 seconds
          setTimeout(() => store.clearComputeProgress(), 3000);
        });

        eventSource.addEventListener('error', (event: MessageEvent) => {
          eventSource.close();
          store.setComputeProgress({
            status: 'failed',
            phase: 'error',
            message: 'Connection to progress stream lost',
            nodes_created: 0,
            edges_created: 0,
            progress_pct: 0,
          });
          setTimeout(() => store.clearComputeProgress(), 5000);
        });

        eventSource.addEventListener('timeout', () => {
          eventSource.close();
          store.clearComputeProgress();
        });

      } catch (err: any) {
        notify.error('Failed to start graph computation');
        store.clearComputeProgress();
      }
    }

    async function loadVendorHub() {
      store.loading = true;
      try {
        const response = await graphExplorerApiService.getVendorHubGraph(20);
        if (response.success && response.nodes?.length > 0) {
          store.setGraphData(
            response.nodes,
            response.edges,
            undefined,
            response.hub_node_ids,
            response.vendor_edge_counts,
          );
          await nextTick();
          setTimeout(() => fitView({ padding: 0.15 }), 150);
        }
      } catch (err: any) {
        // Fallback to all graph
        await loadAllGraph();
      } finally {
        store.loading = false;
      }
    }

    async function loadAllGraph() {
      store.loading = true;
      try {
        const response = await graphExplorerApiService.getAllGraph();
        if (response.success && response.nodes?.length > 0) {
          store.setGraphData(response.nodes, response.edges);
          await nextTick();
          setTimeout(() => fitView({ padding: 0.1 }), 100);
        }
      } catch (err: any) {
        // Non-critical, canvas stays empty
      } finally {
        store.loading = false;
      }
    }

    async function loadAnomalies() {
      store.loading = true;
      try {
        const response = await graphExplorerApiService.getAnomalies(
          ['orphan', 'weak', 'duplicate_vendor', 'amount_outlier'],
          200,
        );
        if (response.success) {
          store.setAnomalies(response.anomalies || [], response.anomaly_counts || {});
        }
      } catch (err: any) {
        notify.error('Failed to load anomalies');
      } finally {
        store.loading = false;
      }
    }

    // Vendor Intelligence table data
    const vendorTableColumns = [
      { name: 'name', label: 'Vendor', field: 'name', align: 'left' as const, sortable: true },
      { name: 'docCount', label: 'Documents', field: 'docCount', align: 'center' as const, sortable: true },
      { name: 'errorRate', label: 'Error Rate', field: 'errorRate', align: 'center' as const, sortable: true },
      { name: 'matchRate', label: 'Match Rate', field: 'matchRate', align: 'center' as const, sortable: true },
      { name: 'poCount', label: 'POs', field: 'poCount', align: 'center' as const, sortable: true },
    ];

    const vendorTableData = computed(() => {
      const vendors = store.nodes.filter((n) => n.node_type === 'vendor');
      const docs = store.nodes.filter((n) => n.node_type === 'document');

      // Build vendor → documents mapping
      const vendorDocs: Record<string, GraphNodeData[]> = {};
      const vendorPOs: Record<string, number> = {};
      for (const edge of store.edges) {
        if (edge.edge_type === 'supplied_by') {
          const docNode = docs.find((d) => d.id === edge.source_node_id);
          if (docNode) {
            (vendorDocs[edge.target_node_id] ||= []).push(docNode);
          }
        }
        if (edge.edge_type === 'references') {
          const po = store.nodes.find((n) => n.id === edge.target_node_id && n.node_type === 'purchase_order');
          if (po) {
            vendorPOs[edge.source_node_id] = (vendorPOs[edge.source_node_id] || 0) + 1;
          }
        }
      }

      return vendors.map((v) => {
        const vDocs = vendorDocs[v.id] || [];
        const errorDocs = vDocs.filter((d) => {
          const status = d.metadata?.status || '';
          return status.includes('error') || status === 'rejected';
        });
        const matchedDocs = vDocs.filter((d) => {
          const match = d.metadata?.po_match_status || '';
          return match.includes('matched') && !match.includes('not_matched');
        });

        return {
          id: v.id,
          name: v.label || v.entity_id,
          docCount: store.vendorEdgeCounts[v.id] || vDocs.length,
          errorRate: vDocs.length > 0 ? Math.round((errorDocs.length / vDocs.length) * 100) : 0,
          matchRate: vDocs.length > 0 ? Math.round((matchedDocs.length / vDocs.length) * 100) : 0,
          poCount: vendorPOs[v.id] || 0,
          node: v,
        };
      }).sort((a, b) => b.docCount - a.docCount);
    });

    function onVendorRowClick(row: any) {
      if (row.node) {
        store.selectNode(row.node);
      }
    }

    function anomalyIcon(type: string): string {
      const icons: Record<string, string> = {
        orphan: 'mdi-link-off',
        weak: 'mdi-link-variant',
        duplicate_vendor: 'mdi-content-duplicate',
        amount_outlier: 'mdi-alert-circle-outline',
      };
      return icons[type] || 'mdi-alert';
    }

    function anomalySeverityColor(type: string): string {
      const colors: Record<string, string> = {
        orphan: 'warning',
        weak: 'info',
        duplicate_vendor: 'negative',
        amount_outlier: 'negative',
      };
      return colors[type] || 'warning';
    }

    async function handleViewChange(view: string) {
      store.clearGraph();
      store.setAnomalies([], {});
      store.clearProcessMining();
      if (view === 'vendor-hub' || view === 'vendor-table') {
        await loadVendorHub();
      } else if (view === 'anomalies') {
        await loadAnomalies();
      } else if (view === 'process-mining') {
        await loadProcessMining();
      }
    }

    async function loadProcessMining() {
      store.loading = true;
      try {
        const [mapResp, varResp, kpiResp] = await Promise.all([
          graphExplorerApiService.getProcessMap(),
          graphExplorerApiService.getProcessVariants(),
          graphExplorerApiService.getProcessKpis(),
        ]);
        if (mapResp.success) {
          store.setProcessMap({ nodes: mapResp.nodes, edges: mapResp.edges, total_transitions: mapResp.total_transitions });
        }
        if (varResp.success) {
          store.setProcessVariants({ variants: varResp.variants, total_cases: varResp.total_cases, conformance_rate: varResp.conformance_rate });
        }
        if (kpiResp.success) {
          store.setProcessKpis(kpiResp);
        }
      } catch (err: any) {
        notify.error('Failed to load process mining data');
      } finally {
        store.loading = false;
      }
    }

    function getBottleneckColor(score: number): string {
      if (score < 0.3) return '#4caf50';  // green
      if (score < 0.7) return '#ff9800';  // amber
      return '#f44336';                     // red
    }

    function formatStatusShort(status: string): string {
      const shorts: Record<string, string> = {
        new: 'New',
        running: 'Run',
        classified: 'Class',
        ready_for_review: 'Review',
        in_review: 'In Rev',
        ready_for_validation: 'Valid',
        validating: 'Valid...',
        validated_pending_approval: 'Approve',
        approved_pending_second_approval: '2nd Appr',
        approved_pending_export: 'Exp',
        validated_pending_export: 'PendExp',
        pending_export: 'PendExp',
        exporting: 'Exp...',
        finished: 'Done',
        error: 'Error',
        export_error: 'ExpErr',
        rejected: 'Reject',
        on_hold: 'Hold',
        restarted: 'Restart',
        workflow: 'WF',
        archived: 'Arch',
      };
      return shorts[status] || status.split('_').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    }

    function onVariantClick(variant: any) {
      if (store.selectedVariant?.rank === variant.rank) {
        store.setSelectedVariant(null);
      } else {
        store.setSelectedVariant(variant);
      }
    }

    // Process Mining VueFlow nodes (left-to-right layout)
    const processFlowNodes = computed({
      get() {
        if (!store.processMap) return [];
        const nodes = store.processMap.nodes;
        // Group by rank for layered layout
        const rankGroups: Record<number, any[]> = {};
        for (const n of nodes) {
          (rankGroups[n.rank] ||= []).push(n);
        }
        const ranks = Object.keys(rankGroups).map(Number).sort((a, b) => a - b);
        const xSpacing = 220;
        const ySpacing = 100;

        const result: any[] = [];
        for (let ri = 0; ri < ranks.length; ri++) {
          const group = rankGroups[ranks[ri]];
          const groupStartY = -(group.length - 1) * ySpacing / 2;
          for (let gi = 0; gi < group.length; gi++) {
            const n = group[gi];
            result.push({
              id: n.id,
              type: 'processNode',
              position: { x: ri * xSpacing, y: 200 + groupStartY + gi * ySpacing },
              data: { ...n },
            });
          }
        }
        return result;
      },
      set() { /* VueFlow may update positions */ },
    });

    const processFlowEdges = computed({
      get() {
        if (!store.processMap) return [];
        const selectedSteps = store.selectedVariant?.steps as string[] | undefined;
        const selectedEdgeSet = new Set<string>();
        if (selectedSteps) {
          for (let i = 0; i < selectedSteps.length - 1; i++) {
            selectedEdgeSet.add(`${selectedSteps[i]}__${selectedSteps[i + 1]}`);
          }
        }

        return store.processMap.edges.map((e: any) => {
          const isHighlighted = selectedSteps ? selectedEdgeSet.has(e.id) : e.is_happy_path;
          const minWidth = 1;
          const maxWidth = 8;
          const width = minWidth + e.weight * (maxWidth - minWidth);

          return {
            id: e.id,
            source: e.source,
            target: e.target,
            label: e.frequency > 1 ? String(e.frequency) : '',
            animated: isHighlighted,
            style: {
              strokeWidth: width,
              stroke: isHighlighted
                ? 'rgba(66, 165, 245, 0.8)'
                : selectedSteps
                  ? 'rgba(255, 255, 255, 0.08)'
                  : 'rgba(255, 255, 255, 0.2)',
            },
            labelStyle: {
              fontSize: '10px',
              fill: isHighlighted ? 'rgba(66, 165, 245, 0.9)' : 'rgba(255, 255, 255, 0.4)',
            },
          };
        });
      },
      set() { /* VueFlow may update */ },
    });

    async function loadStats() {
      try {
        const response = await graphExplorerApiService.getGraphStats();
        if (response.success) {
          store.setStats(response);
        }
      } catch {
        // Stats are optional, don't block UI
      }
    }

    onMounted(async () => {
      await loadStats();
      await loadVendorHub();
    });

    return {
      store,
      PanelPosition,
      searchQuery,
      showSearchResults,
      availableNodeTypes,
      graphViewOptions,
      flowNodes,
      flowEdges,
      nodeTypeChartSeries,
      nodeTypeChartOptions,
      edgeTypeChartSeries,
      edgeTypeChartOptions,
      getNodeColor,
      getNodeSize,
      formatNodeType,
      formatMetadataKey,
      formatMetadataValue,
      formatEdgeType,
      onNodeClick,
      getEdgeForNode,
      navigateToNode,
      handleSearch,
      selectSearchResult,
      handleExpand,
      handleRebuild,
      handleViewChange,
      vendorTableColumns,
      vendorTableData,
      onVendorRowClick,
      anomalyIcon,
      anomalySeverityColor,
      // Process Mining
      processFlowNodes,
      processFlowEdges,
      getBottleneckColor,
      formatStatusShort,
      onVariantClick,
    };
  },
});
</script>

