export const useGraphExplorerStore = defineStore('graphExplorer', {
  state: () => ({
    nodes: [] as GraphNodeData[],
    edges: [] as GraphEdgeData[],
    selectedNode: null as GraphNodeData | null,
    centerNodeId: null as string | null,
    stats: null as GraphStats | null,
    loading: false,
    searchQuery: '',
    searchResults: [] as GraphNodeData[],
    activeTab: 'explorer' as 'explorer' | 'analytics',
    graphView: 'vendor-hub' as 'vendor-hub' | 'vendor-table' | 'anomalies' | 'process-mining',
    hubNodeIds: [] as string[],
    vendorEdgeCounts: {} as Record<string, number>,
    filterNodeTypes: [] as string[],
    filterEdgeTypes: [] as string[],
    minConfidence: 0,
    depth: 1,
    computeProgress: null as {
      status: string;
      phase: string;
      message: string;
      nodes_created: number;
      edges_created: number;
      progress_pct: number;
      docs_total?: number;
      docs_processed?: number;
    } | null,
    computing: false,
    anomalies: [] as any[],
    anomalyCounts: {} as Record<string, number>,
    // Process Mining state
    processMap: null as { nodes: any[]; edges: any[]; total_transitions: number } | null,
    processVariants: null as { variants: any[]; total_cases: number; conformance_rate: number } | null,
    processKpis: null as Record<string, any> | null,
    selectedVariant: null as any | null,
  }),

  getters: {
    nodeCount(): number {
      return this.nodes.length;
    },
    edgeCount(): number {
      return this.edges.length;
    },
    selectedNodeEdges(): GraphEdgeData[] {
      if (!this.selectedNode) return [];
      return this.edges.filter(
        (e) =>
          e.source_node_id === this.selectedNode?.id ||
          e.target_node_id === this.selectedNode?.id,
      );
    },
    connectedNodes(): GraphNodeData[] {
      if (!this.selectedNode) return [];
      const connectedIds = new Set<string>();
      for (const edge of this.selectedNodeEdges) {
        if (edge.source_node_id === this.selectedNode.id) {
          connectedIds.add(edge.target_node_id);
        } else {
          connectedIds.add(edge.source_node_id);
        }
      }
      return this.nodes.filter((n) => connectedIds.has(n.id));
    },
  },

  actions: {
    setGraphData(
      nodes: GraphNodeData[],
      edges: GraphEdgeData[],
      centerNodeId?: string,
      hubNodeIds?: string[],
      vendorEdgeCounts?: Record<string, number>,
    ) {
      this.nodes = nodes;
      this.edges = edges;
      this.centerNodeId = centerNodeId || null;
      this.hubNodeIds = hubNodeIds || [];
      this.vendorEdgeCounts = vendorEdgeCounts || {};
    },

    selectNode(node: GraphNodeData | null) {
      this.selectedNode = node;
    },

    clearGraph() {
      this.nodes = [];
      this.edges = [];
      this.selectedNode = null;
      this.centerNodeId = null;
    },

    setStats(stats: GraphStats) {
      this.stats = stats;
    },

    setSearchResults(results: GraphNodeData[]) {
      this.searchResults = results;
    },

    setComputeProgress(progress: any) {
      this.computeProgress = progress;
      this.computing = progress?.status === 'running' || progress?.status === 'starting';
    },

    clearComputeProgress() {
      this.computeProgress = null;
      this.computing = false;
    },

    setAnomalies(anomalies: any[], counts: Record<string, number>) {
      this.anomalies = anomalies;
      this.anomalyCounts = counts;
    },

    setProcessMap(data: { nodes: any[]; edges: any[]; total_transitions: number }) {
      this.processMap = data;
    },

    setProcessVariants(data: { variants: any[]; total_cases: number; conformance_rate: number }) {
      this.processVariants = data;
    },

    setProcessKpis(data: Record<string, any>) {
      this.processKpis = data;
    },

    setSelectedVariant(variant: any | null) {
      this.selectedVariant = variant;
    },

    clearProcessMining() {
      this.processMap = null;
      this.processVariants = null;
      this.processKpis = null;
      this.selectedVariant = null;
    },
  },
});
